const categories=[['places','مکان‌ها','map-pin','فرودگاه','ایستگاه قطار'],['animals','حیوانات','paw-print','پلنگ','یوزپلنگ'],['food','خوراکی‌ها','utensils','بستنی','فالوده'],['jobs','شغل‌ها','briefcase-business','خلبان','فضانورد'],['objects','وسایل','lamp','چتر','بارانی'],['movies','فیلم و سریال','clapperboard','شیرشاه','کتاب جنگل'],['sports','ورزش','volleyball','والیبال','بسکتبال'],['tech','فناوری','cpu','تبلت','لپ‌تاپ'],['cars','خودرو','car','تاکسی','اتوبوس'],['people','چهره‌ها','user-round','حافظ','سعدی'],['history','تاریخ و جغرافیا','landmark','تخت جمشید','پاسارگاد'],['science','علم و مهندسی','flask-conical','تلسکوپ','میکروسکوپ'],['iran','فرهنگ ایران','flower-2','شب یلدا','نوروز'],['adult','چالش بزرگسال','puzzle','تعارض منافع','تضاد نقش']];
const words=categories.map((c,i)=>({id:'sample-'+i,text:c[3],related:c[4],category:c[0],difficulty:i>8?2:1,age:c[0]==='adult'?18:i>8?12:7,pack:'sample'}));
const normalize=s=>String(s).normalize('NFKC').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[\s\u200c]+/g,' ').trim();
const modes={classic:['جاسوس کلاسیک','یک کلمه، چند نگاه مشکوک','scan-face'],multiple:['چند جاسوس','همدست‌ها همدیگر را نمی‌شناسند','users-round'],undercover:['نفوذی','دو کلمهٔ نزدیک؛ یک تفاوت پنهان','fingerprint'],chameleon:['آفتاب‌پرست','فقط موضوع را می‌دانی','eye'],kids:['کودکانه','کلمه‌های ساده، جمعی صمیمی','smile']};
const mods={speed:['دور سریع','زمان این دور حداکثر ۶۰ ثانیه می‌شود.'],forbidden:['واژه‌های ممنوع','«چیز»، «وسیله» و «جا» ممنوع‌اند؛ میزبان تخلف را یادآوری می‌کند، بدون امتیاز یا جریمه.'],reverse:['جاسوس معکوس','فقط جاسوس کلمه را می‌داند؛ بقیه موضوع را دارند. کشف جاسوس پیروزی گروه و پایان زمان پیروزی جاسوس است؛ حدس نهایی ندارد.'],double:['دردسر دوتایی','دقیقاً دو جاسوس: اول موضوع را می‌داند؛ دوم راهنمای پرسش دارد. هویت همدیگر را نمی‌دانند؛ قوانین برد مشترک است.'],secret:['مأموریت مخفی','یک مأموریت رفتاری خصوصی؛ انجام آن مستقل از برد و باخت ثبت می‌شود.'],events:['اتفاق تصادفی','به درخواست میزبان: توقف کوتاه برای استراحت یا یک پرسش تازه؛ نقشی آشکار نمی‌شود.']};
function shuffle(a,rng=Math.random){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function validate(players,c,pool){if(players.length<4||players.length>20)throw Error('تعداد بازیکنان باید بین ۴ تا ۲۰ نفر باشد.');if(players.some(p=>!normalize(p.name)||!p.ready))throw Error('نام و آمادگی همهٔ بازیکنان را تأیید کنید.');if(!modes[c.mode])throw Error('حالت بازی نامعتبر است.');if(!Number.isInteger(c.spies)||c.spies<1||c.spies>Math.floor((players.length-1)/2))throw Error('تعداد شهروندها باید از جاسوس‌ها بیشتر باشد.');if(c.mode==='multiple'&&c.spies<2)throw Error('حالت چند جاسوس حداقل دو جاسوس نیاز دارد.');if(c.mods.double&&(players.length<5||c.spies!==2))throw Error('دردسر دوتایی به حداقل ۵ بازیکن و دقیقاً ۲ جاسوس نیاز دارد.');if(c.mode==='kids'&&Object.values(c.mods).some(Boolean))throw Error('حالت کودکانه با افزونه‌های پیشرفته ترکیب نمی‌شود.');if(c.mods.reverse&&(c.mode==='undercover'||c.mods.double))throw Error('معکوس با نفوذی یا دردسر دوتایی سازگار نیست.');if(!Number.isInteger(c.seconds)||c.seconds<30||c.seconds>1800||!Number.isInteger(c.rounds)||c.rounds<1||c.rounds>10)throw Error('زمان ۳۰ تا ۱۸۰۰ ثانیه و دورها ۱ تا ۱۰ باشد.');if(!filter(pool,c).length)throw Error('در این انتخاب، کلمهٔ نمونه‌ای موجود نیست؛ موضوع یا سختی را تغییر دهید.');}
function filter(pool,c){return pool.filter(w=>c.categories.includes(w.category)&&(!c.difficulty||w.difficulty===c.difficulty)&&(c.mode!=='kids'||(w.age<=9&&w.category!=='adult'))&&(c.mode!=='undercover'||w.related));}
class Game{
 constructor(players,config,pool=words,history=[],rng=Math.random){validate(players,config,pool);this.players=JSON.parse(JSON.stringify(players));this.config=JSON.parse(JSON.stringify(config));this.pool=filter(pool,config);this.used=[...history];this.round=0;this.results=[];this.next(rng);}
 next(rng=Math.random){if(this.round&&this.phase!=='result')throw Error('دور هنوز تمام نشده است.');if(this.round>=this.config.rounds)return false;this.round++;let pool=this.pool.filter(w=>!this.used.includes(w.id));this.recycled=!pool.length;if(!pool.length)pool=this.pool;this.word=pool[Math.floor(rng()*pool.length)];this.used.push(this.word.id);this.roles=this.players.map(()=>false);shuffle(this.players.map((_,i)=>i),rng).slice(0,this.config.spies).forEach(i=>this.roles[i]=true);this.active=this.players.map(()=>true);this.phase='deal';this.deal=0;this.viewed=false;this.remaining=(this.config.mods.speed?Math.min(this.config.seconds,60):this.config.seconds)*1000;this.total=this.remaining;this.last=null;this.result=null;this.missions=this.players.map((_,i)=>['یک سؤال دربارهٔ اندازه بپرس.','یک پاسخ را با «شاید» شروع کن.','از یک بازیکن ساکت سؤال بپرس.'][i%3]);this.missionDone=this.players.map(()=>false);this.violations=0;this.event=null;this.voteMethod=null;return true;}
 card(i){if(i!==this.deal||this.phase!=='deal')throw Error('این کارت در دسترس نیست.');const spy=this.roles[i],c=this.config;let text,role;if(c.mods.reverse){text=spy?this.word.text:this.category();role=spy?'نقش ویژه':'شهروند';}else if(c.mode==='undercover'){text=spy?this.word.related:this.word.text;role='کلمهٔ شما';}else if(spy){text=c.mode==='chameleon'||c.categoryHint||c.mods.double&&this.roles.slice(0,i).filter(Boolean).length===0?this.category():'کلمه را نمی‌دانی';role=c.mode==='chameleon'?'آفتاب‌پرست':'جاسوس';}else{text=this.word.text;role='شهروند';}this.viewed=true;return {role,text,mission:c.mods.secret?this.missions[i]:null,hint:spy&&c.mods.double?'دربارهٔ کاربردش سؤال کن.':null};}
 category(){return categories.find(c=>c[0]===this.word.category)?.[1]||this.word.category;}
 handoff(){if(this.phase!=='deal'||!this.viewed)throw Error('اول کارت را ببینید.');this.deal++;this.viewed=false;if(this.deal===this.players.length)this.phase='ready';}
 start(now){if(!['ready','paused'].includes(this.phase))return false;this.phase='talk';this.last=now;return true;}
 tick(now){if(this.phase!=='talk')return;const elapsed=Math.max(0,now-this.last);this.last=now;this.remaining=Math.max(0,this.remaining-elapsed);if(!this.remaining)this.finish(this.active.some((a,i)=>a&&this.roles[i])?'spy':'civilian','زمان به پایان رسید');}
 pause(now){this.tick(now);if(this.phase==='talk')this.phase='paused';}
 voting(now,candidates=null){if(candidates){if(this.phase!=='tie')return false;}else{this.tick(now);if(!['talk','paused'].includes(this.phase))return false;}this.phase='vote';this.voteMethod='secret';this.voters=this.active.map((a,i)=>a?i:-1).filter(i=>i>=0);this.candidates=candidates||[...this.voters];this.votes={};this.voter=0;this.totals=null;return true;}
 publicVoting(now){this.tick(now);if(!['talk','paused'].includes(this.phase))return false;this.phase='public-vote';this.voteMethod='public';this.totals=null;this.votes={};this.candidates=this.active.map((a,i)=>a?i:-1).filter(i=>i>=0);return true;}
 publicNominate(index){if(this.phase!=='public-vote'||!Number.isInteger(index)||!this.active[index])return false;this.accused=index;this.phase='accused';return true;}
 publicSkip(now){if(this.phase!=='public-vote')return false;this.phase='paused';return this.start(now);}
 cast(target){if(this.phase!=='vote')return false;const who=this.voters[this.voter],eligible=this.candidates.filter(i=>i!==who&&this.active[i]);if(Object.hasOwn(this.votes,who)||!(target===null&&!eligible.length||eligible.includes(target)))return false;this.votes[who]=target;this.voter++;if(this.voter===this.voters.length){this.totals=this.players.map(()=>0);Object.values(this.votes).forEach(i=>{if(i!==null)this.totals[i]++;});const max=Math.max(...this.totals);this.tied=this.candidates.filter(i=>this.totals[i]===max);if(this.tied.length>1)this.phase='tie';else{this.accused=this.tied[0];this.phase='accused';}}return true;}
 tie(action,index){if(this.phase!=='tie')return false;if(action==='revote')return this.voting(0,this.tied);if(action==='continue'){this.phase='paused';return true;}if(action==='eliminate'&&this.tied.includes(index)){this.accused=index;this.phase='accused';return true;}return false;}
 eligibleGuess(){return this.phase==='accused'&&this.roles[this.accused]&&!this.config.mods.reverse;}
 resolve(guess){if(this.phase!=='accused')return false;if(this.eligibleGuess()&&guess!==null&&normalize(guess)===normalize(this.word.text)){this.finish('spy','حدس نهایی درست بود');return true;}this.active[this.accused]=false;this.eliminated=this.accused;if(!this.roles[this.accused])this.finish('spy','یک شهروند حذف شد');else if(!this.active.some((a,i)=>a&&this.roles[i]))this.finish('civilian','همهٔ جاسوس‌ها شناسایی شدند');else this.phase='eliminated';return true;}
 finish(side,reason){if(this.result)return false;this.result={id:this.round,side,reason,word:this.word.text,roles:[...this.roles]};this.results.push(this.result);this.phase='result';return true;}
 save(){return JSON.parse(JSON.stringify({version:1,state:this}));}
 static restore(raw){if(raw?.version!==1||!raw.state||!Array.isArray(raw.state.players)||raw.state.players.length<4||raw.state.players.length>20||!['deal','ready','talk','paused','vote','public-vote','tie','accused','eliminated','result'].includes(raw.state.phase))throw Error('ذخیرهٔ بازی قابل بازیابی نیست.');const s=raw.state;if(s.roles?.length!==s.players.length||s.active?.length!==s.players.length||!Number.isFinite(s.remaining)||s.remaining<0||s.remaining>s.total)throw Error('ذخیرهٔ بازی نامعتبر است.');const game=Object.assign(Object.create(Game.prototype),JSON.parse(JSON.stringify(s)));if(game.phase==='talk')game.phase='paused';game.last=null;game.viewed=false;return game;}
}
g.SpyEngine={Game,categories,words,modes,mods,shuffle,normalize,validate};
